css:
.mz *,.mz *::before,.mz *::after{box-sizing: border-box; margin: 0; padding: 0;}
.mz .intruso-bloque{display: flex; flex-direction: column; gap: 8px;}
.mz .intruso-fila{display: grid; grid-template-columns: repeat(4, 1fr); gap: 8px;}
.mz .intruso-caja{border: 1.5px solid var(--bosque); border-radius: 8px; padding: 8px 4px; text-align: center; font-size: 13px; font-weight: 700;}
.mz .cal-wrap{display: grid; grid-template-columns: 1fr auto; gap: 16px; align-items: center;}
.mz .cal-tabla{width: 100%; border-collapse: collapse;}
.mz .cal-tabla th,.mz .cal-tabla td{border: 1.5px solid var(--bosque); padding: 4px 2px; text-align: center; font-size: 12px; font-weight: 600; height: 26px;}
.mz .cal-tabla th{background: #f4f4f4; font-weight: 700; font-size: 10.5px;}
.mz .cal-preguntas{display: flex; flex-direction: column; gap: 7px; font-size: 12.5px;}
.mz .cal-preg{display: flex; align-items: center; gap: 6px;}
.mz .cal-hueco{display: inline-block; width: 42px; height: 26px; border: 1.5px solid var(--bosque); border-radius: 5px;}
.mz .cal-hueco.ancho{width: 80px;}
.mz .ordenar-banco{display: flex; gap: 6px; flex-wrap: nowrap; margin-bottom: 8px;}
.mz .banco-dia{flex: 1; border: 1.5px dashed #000; border-radius: 6px; padding: 4px 2px; text-align: center; font-size: 12px; font-weight: 700; background: #f4f4f4;}
.mz .ordenar-huecos{display: grid; grid-template-columns: repeat(7, 1fr); gap: 6px;}
.mz .ord-hueco-caja{display: flex; flex-direction: column; align-items: center; gap: 3px;}
.mz .ord-num{font-family: sans-serif; font-size: 12px; font-weight: 700;}
.mz .ord-hueco{width: 100%; border: 1.5px solid var(--bosque); border-radius: 6px; height: 32px;}
.mz .prob-lista{display: flex; flex-direction: column; gap: 7px;}
.mz .prob{font-size: 13px; line-height: 1.5;}
.mz .hueco-cuadrado{display: inline-block; width: 38px; height: 26px; border: 1.5px solid var(--bosque); border-radius: 5px; vertical-align: middle; margin: 0 4px;}
.mz .hueco-linea{display: inline-block; min-width: 80px; border-bottom: 1.5px solid var(--bosque); height: 18px; vertical-align: bottom; margin: 0 3px;}
.mz .prob{line-height: 1.875 !important;}
